    protected void insertOrderHeader(PurchPurchaseOrderHeader _purchaseOrderHeader)
    {
        PurchTable      purchTable      = PurchTable::find(_purchaseOrderHeader.PurchId);
        InventLocation  inventLocation  = InventLocation::find(purchTable.InventLocationId);
        METPurchTable   metPurchTable   = METPurchTable::findByPurchTable(purchTable.RecID);

        str docNum = _purchaseOrderHeader.PurchOrderDocNum;

        _purchaseOrderHeader.METVersionText             = strFmt('Version %1', substr(docNum, strFind(docNum, '-', 1, 999) + 1, 999));

        if(metPurchTable.POSubSource)
        {
            _purchaseOrderHeader.METOrderToDetails          = strFmt('ABN %1\nVendor number / Sub-source: %2 / %3',
                purchTable.vendTable_OrderAccount().VATNum,
                purchTable.InvoiceAccount,
                metPurchTable.POSubSource);
        }
        else
        {
            _purchaseOrderHeader.METOrderToDetails          = strFmt('ABN %1\nVendor number: %2',
                purchTable.vendTable_OrderAccount().VATNum,
                purchTable.OrderAccount);        
        }

        if(purchTable.PurchStatus == PurchStatus::Canceled)
            _purchaseOrderHeader.METHeaderStatus = '*** CANCELLED ***';
        else
        {
            if(strStartsWith(metPurchTable.POSubSource, 'UB'))
               _purchaseOrderHeader.METHeaderStatus = '*** UNDERBOND PURCHASE ORDER ***';
        }

        _purchaseOrderHeader.METDeliveryDate            = purchTable.DeliveryDate;

        if(purchTable.ReqAttention)
        {
            _purchaseOrderHeader.METSpecialInstructions     = 'Special PO instructions: ' + purchTable.ReqAttention;
        }

        _purchaseOrderHeader.METContactName             = purchTable.editContactPersonName(false, '');
        _purchaseOrderHeader.METContactEmail            = purchTable.contactPerson().email();
        _purchaseOrderHeader.METContactPhone            = purchTable.contactPerson().phone();
        _purchaseOrderHeader.METReceivingDockDetails    = ''; // *** todo - primary contact against warehouse? clarify reqs.
        _purchaseOrderHeader.METLegendText              = VendFormletterParameters::find().METPurchOrderReportLegendText;

        Email deliverToEmail = VendTable::find(purchTable.OrderAccount).email();

        str deliveryTimeSlotRequired;

        _purchaseOrderHeader.METDeliveryAddressWithAdditionalDetails = _purchaseOrderHeader.DeliveryAddress;
        _purchaseOrderHeader.METDeliveryAddressDetail2 = _purchaseOrderHeader.DeliveryAddress;

        if(deliveryTimeSlotRequired)
            _purchaseOrderHeader.METDeliveryAddressDetail2 += strFmt('\nDelivery Time Slot Required: %1', deliveryTimeSlotRequired); 

        if(deliverToEmail)
        {
            _purchaseOrderHeader.METDeliveryAddressWithAdditionalDetails += '\n' + deliverToEmail;
            _purchaseOrderHeader.METDeliveryAddressDetail2 += strFmt('\nContact: %1', deliverToEmail);
        }

        next insertOrderHeader(_purchaseOrderHeader);
    }

    protected void insertOrderLine(PurchPurchaseOrderTmp _purchaseOrderTmp)
    {
        PurchLine           purchLine           = PurchLine::findInventTransId(_purchaseOrderTmp.PurchLineInventTransId);
        InventDim           inventDim           = purchLine.inventDim();
        VendPurchOrderJour  purchJour;

        purchJour = VendPurchOrderJour::findRecId(_purchaseOrderTmp.JournalRecId);
               
        PurchLineAllVersions lineAllVersions;
        select firstonly lineAllVersions
            where   lineAllVersions.PurchTableVersionRecId  == purchJour.PurchTableVersion
            &&      lineAllVersions.InventTransId           == _purchaseOrderTmp.PurchLineInventTransId;

        MetItemSiteSettingsSetup metItemSiteSettings;
        // NB no indexes or find methods defined on this table at time of writing.
        select firstonly metItemSiteSettings
            where   metItemSiteSettings.ItemId          == purchLine.ItemId
            &&      metItemSiteSettings.InventSiteId    == inventDim.InventSiteId;          

        _purchaseOrderTmp.METGTIN                   = purchLine.BarCode;   
        _purchaseOrderTmp.METTi                     = metItemSiteSettings.CartonPerLayer;
        _purchaseOrderTmp.METHi                     = metItemSiteSettings.Layers;
        _purchaseOrderTmp.METMLOR                   = metItemSiteSettings.TempRcvLimit ? metItemSiteSettings.TempRcvLimit : 99;
        _purchaseOrderTmp.METAmountIncTax           = lineAllVersions.LineAmount + lineAllVersions.ConfirmedTaxAmount;
        _purchaseOrderTmp.METPurchPriceIncTax       = _purchaseOrderTmp.METAmountIncTax / lineAllVersions.PurchQty;
        _purchaseOrderTmp.TaxAmount                 = lineAllVersions.ConfirmedTaxAmount;

        if(_purchaseOrderTmp.METTi && _purchaseOrderTmp.METHi)
        {
            _purchaseOrderTmp.METPalletQty = _purchaseOrderTmp.Qty / _purchaseOrderTmp.METTi / _purchaseOrderTmp.METHi;
        }

        next insertOrderLine(_purchaseOrderTmp);
    }
